//! Runs real libmpv with no audio or video output and checks that the app's
//! event plumbing (`src/mpv_events.rs`) reports what the UI depends on.
//!
//! The app is a binary crate, so this test pulls the module in by path rather
//! than through a library. The media is generated by ffmpeg's lavfi, so no
//! sample files are needed.

#[allow(dead_code)]
#[path = "../src/mpv_events.rs"]
mod mpv_events;

use std::sync::Arc;
use std::time::{Duration, Instant};

use libmpv2::Mpv;
use mpv_events::MpvUpdate;

/// Two seconds of test pattern, as a file mpv can open.
const TEST_SOURCE: &str = "av://lavfi:testsrc=duration=2:size=160x120:rate=10";

/// How long to wait for any one expected update before failing.
const TIMEOUT: Duration = Duration::from_secs(15);

fn headless_mpv() -> Arc<Mpv> {
    let mpv = Mpv::with_initializer(|init| {
        init.set_property("vo", "null")?;
        init.set_property("ao", "null")?;
        init.set_property("idle", "yes")?;
        init.set_property("keep-open", false)?;
        Ok(())
    })
    .expect("libmpv should initialize");
    mpv_events::observe(&mpv).expect("observing properties should succeed");
    Arc::new(mpv)
}

/// Reads batches until one update satisfies `want`, returning everything seen.
fn wait_for(mpv: &Arc<Mpv>, what: &str, want: impl Fn(&MpvUpdate) -> bool) -> Vec<MpvUpdate> {
    let deadline = Instant::now() + TIMEOUT;
    let mut seen = Vec::new();
    loop {
        let batch = mpv_events::next_batch(mpv, || Instant::now() >= deadline);
        let found = batch.iter().any(&want);
        seen.extend(batch);
        if found {
            return seen;
        }
        assert!(
            Instant::now() < deadline,
            "timed out waiting for {what}; saw {seen:?}"
        );
    }
}

#[test]
fn reports_initial_state_while_idle() {
    let mpv = headless_mpv();
    let seen = wait_for(&mpv, "Idle(true)", |u| matches!(u, MpvUpdate::Idle(true)));
    assert!(
        !seen.iter().any(|u| matches!(u, MpvUpdate::Error(_))),
        "unexpected error: {seen:?}"
    );
}

#[test]
fn plays_a_file_through_to_the_end() {
    let mpv = headless_mpv();
    mpv.command("loadfile", &[TEST_SOURCE]).unwrap();

    let mut seen = wait_for(&mpv, "FileLoaded", |u| matches!(u, MpvUpdate::FileLoaded));
    seen.extend(wait_for(
        &mpv,
        "position past 0.5s",
        |u| matches!(u, MpvUpdate::Position(p) if *p > 0.5),
    ));
    assert!(
        seen.iter().any(|u| matches!(u, MpvUpdate::Idle(false))),
        "mpv should leave idle when a file loads: {seen:?}"
    );
    assert!(
        seen.iter()
            .any(|u| matches!(u, MpvUpdate::Duration(d) if (*d - 2.0).abs() < 0.5)),
        "duration should be about 2s: {seen:?}"
    );

    // With keep-open off, mpv returns to idle when the file ends.
    wait_for(&mpv, "Idle(true) at end of file", |u| {
        matches!(u, MpvUpdate::Idle(true))
    });
}

#[test]
fn reports_pause_and_volume_changes() {
    let mpv = headless_mpv();
    mpv.command("loadfile", &[TEST_SOURCE]).unwrap();
    wait_for(&mpv, "FileLoaded", |u| matches!(u, MpvUpdate::FileLoaded));

    mpv.command("cycle", &["pause"]).unwrap();
    wait_for(&mpv, "Paused(true)", |u| {
        matches!(u, MpvUpdate::Paused(true))
    });

    mpv.set_property("volume", 42.0).unwrap();
    wait_for(
        &mpv,
        "Volume(42)",
        |u| matches!(u, MpvUpdate::Volume(v) if (*v - 42.0).abs() < 0.01),
    );
}

#[test]
fn forwards_key_binding_script_messages() {
    // The video window sends `script-message toggle-fullscreen` (and
    // `open-file <path>`) through mpv and expects them back as ClientMessage.
    let mpv = headless_mpv();
    mpv.command("script-message", &["toggle-fullscreen"])
        .unwrap();
    wait_for(
        &mpv,
        "ClientMessage(toggle-fullscreen)",
        |u| matches!(u, MpvUpdate::ClientMessage(args) if *args == ["toggle-fullscreen"]),
    );
}

#[test]
fn recovers_after_a_file_fails_to_load() {
    let mpv = headless_mpv();
    mpv.command("loadfile", &["this-file-does-not-exist.mp4"])
        .unwrap();
    // A failed load must not wedge the event loop: the next file still plays.
    mpv.command("loadfile", &[TEST_SOURCE, "append-play"])
        .unwrap();
    wait_for(&mpv, "FileLoaded for the second file", |u| {
        matches!(u, MpvUpdate::FileLoaded)
    });
}
